(5415615, 777278, 101256, '<td valign="top">Too much of the body is hidden and the depth-of-field control is lacking.</td>', 'Too much of the body is hidden and the depth-of-field control is lacking.', '2009-04-02 19:49:44.000000', NULL, 1),
(5415617, 778231, 101256, '<td valign="top">Good image, good detail, but something is missing to make it an excellent image.</td>', 'Good image, good detail, but something is missing to make it an excellent image.', '2009-04-02 19:50:47.000000', NULL, 1),
(5415619, 777400, 101256, '<td valign="top">Rich detail, solid depth of field control which is important in these types of images.  Well done.</td>', 'Rich detail, solid depth of field control which is important in these types of images.  Well done.', '2009-04-02 19:51:24.000000', NULL, 1),
(5415632, 778638, 101256, '<td valign="top">At first I couldn''t tell what this was - I thought originally it was a whale but that didn''t make any sense. You had something in mind, but I can''t tell what. When in doubt - give it up.</td>', 'At first I couldn''t tell what this was - I thought originally it was a whale but that didn''t make any sense. You had something in mind, but I can''t tell what. When in doubt - give it up.', '2009-04-02 19:58:47.000000', NULL, 1),
(5415634, 778225, 101256, '<td valign="top">Good detail, but the overall appearance is somewhat bland - to high an exposure I suspect.</td>', 'Good detail, but the overall appearance is somewhat bland - to high an exposure I suspect.', '2009-04-02 19:59:31.000000', NULL, 1),
(5415639, 778630, 104010, '<td valign="top">Itching?</td>', 'Itching?', '2009-04-02 20:04:23.000000', NULL, 1),
(5415644, 777912, 101256, '<td valign="top">A little less exposure would have made this a great image. Unique angle.</td>', 'A little less exposure would have made this a great image. Unique angle.', '2009-04-02 20:08:18.000000', NULL, 1),
(5415648, 778304, 101256, '<td valign="top">Good  use of lighting and an effective composition.</td>', 'Good  use of lighting and an effective composition.', '2009-04-02 20:09:24.000000', NULL, 1),
(5415651, 778380, 101256, '<td valign="top">The flash created a halo effect along the right side of the horse''s snout - almost as if you over sharpened the image a little. Minor flaw though.</td>', 'The flash created a halo effect along the right side of the horse''s snout - almost as if you over sharpened the image a little. Minor flaw though.', '2009-04-02 20:11:03.000000', NULL, 1),
(5415653, 777479, 101256, '<td valign="top">Dogs, cars and windows - perfect combination.  I like it just because.</td>', 'Dogs, cars and windows - perfect combination.  I like it just because.', '2009-04-02 20:11:43.000000', NULL, 1),
(5415655, 778153, 101256, '<td valign="top">The upper right glow ruins the overall effect of the color - this might have worked better in black and white.</td>', 'The upper right glow ruins the overall effect of the color - this might have worked better in black and white.', '2009-04-02 20:12:30.000000', NULL, 1),
(5415656, 778236, 66967, '<td valign="top">Wonderful capture.<br/><br/><i>Message edited by author 2009-04-09 07:11:20.</i></td>', 'Wonderful capture.', '2009-04-02 20:12:55.000000', '2009-04-09 08:11:20.000000', 1),
(5415668, 778559, 101256, '<td valign="top">This is a great image - wonderful.</td>', 'This is a great image - wonderful.', '2009-04-02 20:18:30.000000', NULL, 1),
(5415670, 777941, 101256, '<td valign="top">The subject is not as sharp as it should be and the composition shows too much nest and not enough bird.</td>', 'The subject is not as sharp as it should be and the composition shows too much nest and not enough bird.', '2009-04-02 20:19:46.000000', NULL, 1),
(5415671, 777653, 104010, '<td valign="top">This photo is quite intriguing!</td>', 'This photo is quite intriguing!', '2009-04-02 20:19:47.000000', NULL, 1),
(5415674, 777813, 104010, '<td valign="top">Fantastic macro photo!</td>', 'Fantastic macro photo!', '2009-04-02 20:20:09.000000', NULL, 1),
(5415676, 778350, 104010, '<td valign="top">Love the color combination!</td>', 'Love the color combination!', '2009-04-02 20:20:28.000000', NULL, 1),
(5415678, 777933, 101256, '<td valign="top">Good capture and good composition. Unfortunately the over sharpening halo around the body of the robin is a serious defect.</td>', 'Good capture and good composition. Unfortunately the over sharpening halo around the body of the robin is a serious defect.', '2009-04-02 20:20:51.000000', NULL, 1),
(5415679, 777198, 101256, '<td valign="top">An average capture in terms of composition, but the detail is excellant.</td>', 'An average capture in terms of composition, but the detail is excellant.', '2009-04-02 20:22:02.000000', NULL, 1),
(5415680, 777035, 101256, '<td valign="top">Depth of field problems probably from using the wrong lens is a negative. The overall bland nature of the image also works against the color scheme.</td>', 'Depth of field problems probably from using the wrong lens is a negative. The overall bland nature of the image also works against the color scheme.', '2009-04-02 20:22:59.000000', NULL, 1),
(5415683, 778054, 101256, '<td valign="top">The foreground ruins what otherwise would have been a great image. This is always a problem with wildlife - it requires patience and a clear shot to the subject to be truly effective.</td>', 'The foreground ruins what otherwise would have been a great image. This is always a problem with wildlife - it requires patience and a clear shot to the subject to be truly effective.', '2009-04-02 20:24:20.000000', NULL, 1),
(5415687, 777593, 101256, '<td valign="top">Needs a lot more focus to be good.</td>', 'Needs a lot more focus to be good.', '2009-04-02 20:24:56.000000', NULL, 1),
(5415688, 778666, 101256, '<td valign="top">I like this, but its a little busy with the partial body forms of the other sheep.</td>', 'I like this, but its a little busy with the partial body forms of the other sheep.', '2009-04-02 20:25:54.000000', NULL, 1),
(5415689, 778341, 101256, '<td valign="top">Very clever - a winner in my book.</td>', 'Very clever - a winner in my book.', '2009-04-02 20:26:15.000000', NULL, 1),
(5415690, 778283, 101256, '<td valign="top">Nice crop, good detail and effective use of foreground and background. Well done.</td>', 'Nice crop, good detail and effective use of foreground and background. Well done.', '2009-04-02 20:26:50.000000', NULL, 1),
(5415693, 776685, 101256, '<td valign="top">Too much motion led to some unfortunate double imaging on the foreleg that just makes one''s eyes water trying to find resolution.</td>', 'Too much motion led to some unfortunate double imaging on the foreleg that just makes one''s eyes water trying to find resolution.', '2009-04-02 20:29:46.000000', NULL, 1),
(5415696, 777863, 101256, '<td valign="top">Outstanding image.</td>', 'Outstanding image.', '2009-04-02 20:31:14.000000', NULL, 1),
(5415706, 778191, 101256, '<td valign="top">Interesting angle, rich detail and a bit of goofy looks made a terrific image. Well done.</td>', 'Interesting angle, rich detail and a bit of goofy looks made a terrific image. Well done.', '2009-04-02 20:33:09.000000', NULL, 1),
(5415708, 777040, 101256, '<td valign="top">I think I might have called this "Tough Enough".  :&gt;) Nice composition and very effective conversion to black and white.</td>', 'I think I might have called this "Tough Enough".  :>) Nice composition and very effective conversion to black and white.', '2009-04-02 20:33:50.000000', NULL, 1),
(5415711, 777213, 101256, '<td valign="top">Startling in its emotional essence. Very effective.</td>', 'Startling in its emotional essence. Very effective.', '2009-04-02 20:37:35.000000', NULL, 1),
(5415713, 778363, 101256, '<td valign="top">An Audubon Society quality image - well done.</td>', 'An Audubon Society quality image - well done.', '2009-04-02 20:38:20.000000', NULL, 1),
(5415716, 778293, 101256, '<td valign="top">Another unusual and very unique angle - excellant.</td>', 'Another unusual and very unique angle - excellant.', '2009-04-02 20:39:22.000000', NULL, 1),
(5415717, 778034, 101256, '<td valign="top">A National Geographic quality image - very effective.</td>', 'A National Geographic quality image - very effective.', '2009-04-02 20:40:07.000000', NULL, 1),
(5415718, 777653, 101256, '<td valign="top">Excellant depth of field control, rich in detail and worked well with the lighting.  Well done.</td>', 'Excellant depth of field control, rich in detail and worked well with the lighting.  Well done.', '2009-04-02 20:40:51.000000', NULL, 1),
(5415719, 778364, 101256, '<td valign="top">Another Audubon Society quality image - I keep saying it, but DOF control in these images are a requirement and this demonstrates the reason why.</td>', 'Another Audubon Society quality image - I keep saying it, but DOF control in these images are a requirement and this demonstrates the reason why.', '2009-04-02 20:41:51.000000', NULL, 1),
(5415720, 777811, 101256, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2009-04-02 20:42:16.000000', NULL, 1),
(5415732, 778540, 101256, '<td valign="top">Can''t complain about anything.  Well done.</td>', 'Can''t complain about anything.  Well done.', '2009-04-02 20:47:07.000000', NULL, 1),
(5415735, 778246, 101256, '<td valign="top">This would have been much more effective if it had been taken at an angle rather than head on.</td>', 'This would have been much more effective if it had been taken at an angle rather than head on.', '2009-04-02 20:48:03.000000', NULL, 1),
(5415751, 778017, 101256, '<td valign="top">Very detailed, perfect DOF - this works on several different levels. Very nice.</td>', 'Very detailed, perfect DOF - this works on several different levels. Very nice.', '2009-04-02 20:55:55.000000', NULL, 1),
(5415754, 778334, 101256, '<td valign="top">Way over done and the unnatural halo around the body just finishes the image off.</td>', 'Way over done and the unnatural halo around the body just finishes the image off.', '2009-04-02 20:57:04.000000', NULL, 1),
(5415757, 776642, 101256, '<td valign="top">Capturing black faces on animals is difficult, but you''ve managed to pull this off perfectly. Well done.</td>', 'Capturing black faces on animals is difficult, but you''ve managed to pull this off perfectly. Well done.', '2009-04-02 20:57:53.000000', NULL, 1),
(5415760, 778423, 101256, '<td valign="top">A great image rich in detail - excellant DOF control.</td>', 'A great image rich in detail - excellant DOF control.', '2009-04-02 20:58:22.000000', NULL, 1),
(5415824, 778365, 54265, '<td valign="top">It looks too much like an illustration to me</td>', 'It looks too much like an illustration to me', '2009-04-02 21:42:19.000000', NULL, 1),
(5415829, 776637, 54265, '<td valign="top">I wish you got the face in focus rather than the branches</td>', 'I wish you got the face in focus rather than the branches', '2009-04-02 21:43:09.000000', NULL, 1),
(5415837, 777755, 54265, '<td valign="top">You need to fix your white balance here</td>', 'You need to fix your white balance here', '2009-04-02 21:45:23.000000', NULL, 1),
(5415850, 778657, 101256, '<td valign="top">This should have been an entry in the Free Study - yeah, thers is an animal in it, but it''s not a strictly a fauna. It''s a terrific composition - very clevel use of reflections and if it had been in Free Study, its a potential winner.  In this challenge, not so much.</td>', 'This should have been an entry in the Free Study - yeah, thers is an animal in it, but it''s not a strictly a fauna. It''s a terrific composition - very clevel use of reflections and if it had been in Free Study, its a potential winner.  In this challenge, not so much.', '2009-04-02 21:48:30.000000', NULL, 1),
(5415854, 777903, 101256, '<td valign="top">A great character study of a beautiful raptor. The detail is excellant.</td>', 'A great character study of a beautiful raptor. The detail is excellant.', '2009-04-02 21:50:11.000000', NULL, 1),
(5415858, 777090, 101256, '<td valign="top">A study in how a candid wildlife image shold be done - nothing in the way of the subject - perfect framing with one minor flaw.  Well done.</td>', 'A study in how a candid wildlife image shold be done - nothing in the way of the subject - perfect framing with one minor flaw.  Well done.', '2009-04-02 21:51:05.000000', NULL, 1),
(5415860, 777901, 101256, '<td valign="top">A great capture, but a little close on the composition. Minor flaw. Well done.</td>', 'A great capture, but a little close on the composition. Minor flaw. Well done.', '2009-04-02 21:52:01.000000', NULL, 1),
(5415864, 777307, 101256, '<td valign="top">A nice candid,although I would like to see a closer crop of the bottom - that''s a DOF problem.  Other than that, it''s great.</td>', 'A nice candid,although I would like to see a closer crop of the bottom - that''s a DOF problem.  Other than that, it''s great.', '2009-04-02 21:53:14.000000', NULL, 1),
(5415866, 776482, 101256, '<td valign="top">A ball is a dogs best friend.  :&gt;) Cute image.</td>', 'A ball is a dogs best friend.  :>) Cute image.', '2009-04-02 21:54:07.000000', NULL, 1),
(5415869, 776759, 101256, '<td valign="top">This is very clever and a very different look at the subject matter. Well done.</td>', 'This is very clever and a very different look at the subject matter. Well done.', '2009-04-02 21:55:15.000000', NULL, 1),
(5415874, 777404, 101256, '<td valign="top">Is that Chip or Dale? Cute image - highly amusing.</td>', 'Is that Chip or Dale? Cute image - highly amusing.', '2009-04-02 21:57:03.000000', NULL, 1),
(5415878, 778477, 101256, '<td valign="top">Not perfect, but very close. Nice composition, very detailed and effective.</td>', 'Not perfect, but very close. Nice composition, very detailed and effective.', '2009-04-02 21:58:35.000000', NULL, 1),
(5415881, 778470, 101256, '<td valign="top">Powerful image - caught all the tension of the moment.  Well done.</td>', 'Powerful image - caught all the tension of the moment.  Well done.', '2009-04-02 21:59:32.000000', NULL, 1),
(5415883, 778371, 101256, '<td valign="top">Much too dark - needs a lighter touch on both the exposure and conversion compensation.</td>', 'Much too dark - needs a lighter touch on both the exposure and conversion compensation.', '2009-04-02 22:00:43.000000', NULL, 1),
(5415895, 778508, 101256, '<td valign="top">The ancient Roman and Greek philosophers often argued about if a horse ever had all four feet off the ground at the same time. If only they had digital cameras. :&gt;)  A great action shot of strong beautiful animals.</td>', 'The ancient Roman and Greek philosophers often argued about if a horse ever had all four feet off the ground at the same time. If only they had digital cameras. :>)  A great action shot of strong beautiful animals.', '2009-04-02 22:09:53.000000', NULL, 1),
(5415897, 778425, 101256, '<td valign="top">Beautiful detail - excellant DOF control - strong and purposeful. Well done.</td>', 'Beautiful detail - excellant DOF control - strong and purposeful. Well done.', '2009-04-02 22:10:51.000000', NULL, 1),
(5415901, 778286, 101256, '<td valign="top">Nicely composed and great detail, but the white bloom on the beak is distracting and effects the overall impact of the image. Also the reflection in the right eye detracts from the overall effect.</td>', 'Nicely composed and great detail, but the white bloom on the beak is distracting and effects the overall impact of the image. Also the reflection in the right eye detracts from the overall effect.', '2009-04-02 22:12:56.000000', NULL, 1),
(5415905, 778262, 101256, '<td valign="top">A nice image that could be improved by judicious cropping of the top of the image.</td>', 'A nice image that could be improved by judicious cropping of the top of the image.', '2009-04-02 22:13:38.000000', NULL, 1),
(5415909, 778216, 101256, '<td valign="top">Just slightly out of focus which is a serious defect in an otherwise nicely composed image.</td>', 'Just slightly out of focus which is a serious defect in an otherwise nicely composed image.', '2009-04-02 22:15:45.000000', NULL, 1),
(5415912, 777748, 101256, '<td valign="top">Its the Librarian from Unseen University!! Terrific image - captured the essence of this ape''s personality.</td>', 'Its the Librarian from Unseen University!! Terrific image - captured the essence of this ape''s personality.', '2009-04-02 22:16:35.000000', NULL, 1),
(5415914, 778486, 101256, '<td valign="top">A sure fire winner- the overall detail, the excellant use of tone and shadow and the terrific expression is perfect.  Well done.</td>', 'A sure fire winner- the overall detail, the excellant use of tone and shadow and the terrific expression is perfect.  Well done.', '2009-04-02 22:16:47.000000', NULL, 1),
(5415915, 777489, 101256, '<td valign="top">Perfect.</td>', 'Perfect.', '2009-04-02 22:16:50.000000', NULL, 1),
(5415916, 777032, 101256, '<td valign="top">A very unique and clever conversion. Well done.</td>', 'A very unique and clever conversion. Well done.', '2009-04-02 22:16:58.000000', NULL, 1),
(5415917, 777813, 101256, '<td valign="top">Perfect.</td>', 'Perfect.', '2009-04-02 22:17:01.000000', NULL, 1),
(5415919, 777158, 101256, '<td valign="top">Purrfect.</td>', 'Purrfect.', '2009-04-02 22:17:08.000000', NULL, 1),
(5415920, 777740, 101256, '<td valign="top">Another Audubon Society image - richly detailed.</td>', 'Another Audubon Society image - richly detailed.', '2009-04-02 22:17:11.000000', NULL, 1),
(5415921, 778332, 101256, '<td valign="top">Whoever is taking these needs to go pro. Perfect.</td>', 'Whoever is taking these needs to go pro. Perfect.', '2009-04-02 22:17:23.000000', NULL, 1),
(5415922, 777145, 101256, '<td valign="top">Perfect - simply outstanding.</td>', 'Perfect - simply outstanding.', '2009-04-02 22:17:29.000000', NULL, 1),
(5415923, 778170, 101256, '<td valign="top">Perfect.</td>', 'Perfect.', '2009-04-02 22:17:37.000000', NULL, 1),
