(5416047, 778364, 79738, '<td valign="top">Lovely Peregrine!  His colors are so vivid and beautiful</td>', 'Lovely Peregrine!  His colors are so vivid and beautiful', '2009-04-02 23:17:18.000000', NULL, 1),
