(5416170, 778244, 20956, '<td valign="top">Out of focus else it would merit a better score.</td>', 'Out of focus else it would merit a better score.', '2009-04-03 00:37:13.000000', NULL, 1),
(5416172, 778022, 20956, '<td valign="top">I like b&amp;w but this bird must have some pretty colors. Would have liked it in color.</td>', 'I like b&w but this bird must have some pretty colors. Would have liked it in color.', '2009-04-03 00:38:41.000000', NULL, 1),
(5416174, 778153, 20956, '<td valign="top">Seems to have a weird tinge of red.</td>', 'Seems to have a weird tinge of red.', '2009-04-03 00:39:37.000000', NULL, 1),
(5416175, 777180, 20956, '<td valign="top">Not quite in focus and could use some cropping.</td>', 'Not quite in focus and could use some cropping.', '2009-04-03 00:40:29.000000', NULL, 1),
(5416176, 778267, 20956, '<td valign="top">Too dark.</td>', 'Too dark.', '2009-04-03 00:40:48.000000', NULL, 1),
