(5416181, 778446, 20956, '<td valign="top">Different but nice.</td>', 'Different but nice.', '2009-04-03 00:44:08.000000', NULL, 1),
(5416182, 777198, 20956, '<td valign="top">Overall a little bit overexposed.</td>', 'Overall a little bit overexposed.', '2009-04-03 00:44:45.000000', NULL, 1),
(5416185, 778447, 20956, '<td valign="top">Your subjects are to centered in the middle and the photo is tilted.</td>', 'Your subjects are to centered in the middle and the photo is tilted.', '2009-04-03 00:46:09.000000', NULL, 1),
(5416191, 776660, 20956, '<td valign="top">Very nice attemp at a action photo, which I know is hard to capture, but nothing is in focus.</td>', 'Very nice attemp at a action photo, which I know is hard to capture, but nothing is in focus.', '2009-04-03 00:48:23.000000', NULL, 1),
(5416193, 777762, 30454, '<td valign="top">Great capture, good exposure and very good focus. One of my top score, good luck.</td>', 'Great capture, good exposure and very good focus. One of my top score, good luck.', '2009-04-03 00:49:14.000000', NULL, 1),
(5416194, 777307, 20956, '<td valign="top">Your photo needs some cropping top and bottom, maybe it should have been shot landscape instead of portrait.</td>', 'Your photo needs some cropping top and bottom, maybe it should have been shot landscape instead of portrait.', '2009-04-03 00:49:55.000000', NULL, 1),
(5416197, 777153, 20956, '<td valign="top">Nice crop but a lot of people are not going to rate this very high because it is such a small photo.</td>', 'Nice crop but a lot of people are not going to rate this very high because it is such a small photo.', '2009-04-03 00:50:55.000000', NULL, 1),
(5416201, 777653, 30454, '<td valign="top">WOW, excellent. So cute, great composition. My pick for the ribbon, good luck.</td>', 'WOW, excellent. So cute, great composition. My pick for the ribbon, good luck.', '2009-04-03 00:53:30.000000', NULL, 1),
(5416202, 778333, 20956, '<td valign="top">Very nice, I like the background in the photo. It gives the frog a sense of vulnerablity. The b&amp;w works well giving an even greater feel of the night.</td>', 'Very nice, I like the background in the photo. It gives the frog a sense of vulnerablity. The b&w works well giving an even greater feel of the night.', '2009-04-03 00:53:41.000000', NULL, 1),
(5416204, 778001, 20956, '<td valign="top">Seems to be overprocessed.</td>', 'Seems to be overprocessed.', '2009-04-03 00:54:16.000000', NULL, 1),
(5416207, 777414, 20956, '<td valign="top">Nice pose. The overall photo seems overexposed.</td>', 'Nice pose. The overall photo seems overexposed.', '2009-04-03 00:55:20.000000', NULL, 1),
(5416210, 777158, 20956, '<td valign="top">Now that is an in-your-face photo. Well focused.</td>', 'Now that is an in-your-face photo. Well focused.', '2009-04-03 00:56:13.000000', NULL, 1),
(5416213, 776847, 20956, '<td valign="top">Very nice but seems a little overexposed.</td>', 'Very nice but seems a little overexposed.', '2009-04-03 00:56:35.000000', NULL, 1),
