(5417384, 778451, 104643, '<td valign="top">What a close-up!  Very "eye-catching" photo.</td>', 'What a close-up!  Very "eye-catching" photo.', '2009-04-03 18:59:50.000000', NULL, 1),
(5417387, 777277, 104643, '<td valign="top">Gorgeous photo! You have captured such grace and sharpness.</td>', 'Gorgeous photo! You have captured such grace and sharpness.', '2009-04-03 19:00:49.000000', NULL, 1),
