(5417804, 778576, 30454, '<td valign="top">So cute, I like the way you crop it. The DOF is so nice, you can almost feel the 3D effect. Not a fan of thick border here. One of my high score, good luck.</td>', 'So cute, I like the way you crop it. The DOF is so nice, you can almost feel the 3D effect. Not a fan of thick border here. One of my high score, good luck.', '2009-04-03 23:53:53.000000', NULL, 1),
(5417808, 776801, 30454, '<td valign="top">Good idea. I finally figured it out, I think the cat is on the glass. Great execution, good luck.</td>', 'Good idea. I finally figured it out, I think the cat is on the glass. Great execution, good luck.', '2009-04-03 23:54:50.000000', NULL, 1),
(5417812, 777811, 30454, '<td valign="top">Great shot here. The rain drops are very nice addition. One of my high score, good luck.</td>', 'Great shot here. The rain drops are very nice addition. One of my high score, good luck.', '2009-04-03 23:57:23.000000', NULL, 1),
(5417816, 776514, 30454, '<td valign="top">Oh, WOW. I like the color contrast here. Wonderful dark blue on light brown rock. Excellent capture. Good Luck.</td>', 'Oh, WOW. I like the color contrast here. Wonderful dark blue on light brown rock. Excellent capture. Good Luck.', '2009-04-03 23:58:24.000000', NULL, 1),
(5417820, 777213, 30454, '<td valign="top">Excellent photo, great story, perfect title. Good Luck.</td>', 'Excellent photo, great story, perfect title. Good Luck.', '2009-04-03 23:59:32.000000', NULL, 1),
(5417824, 778425, 30454, '<td valign="top">Excellent shot here. I would like to see some more color saturation. Nice sharp focus and composition, Good luck.</td>', 'Excellent shot here. I would like to see some more color saturation. Nice sharp focus and composition, Good luck.', '2009-04-04 00:01:07.000000', NULL, 1),
(5417828, 777287, 30454, '<td valign="top">Excellent framing, great colors and focus. Good Luck.</td>', 'Excellent framing, great colors and focus. Good Luck.', '2009-04-04 00:02:09.000000', NULL, 1),
(5417834, 777984, 30454, '<td valign="top">Nice subject. I wish, it was looking at the camera though.</td>', 'Nice subject. I wish, it was looking at the camera though.', '2009-04-04 00:04:56.000000', NULL, 1),
(5417835, 778286, 30454, '<td valign="top">WOW, what a stare. Great capture, one of my high score, good luck.</td>', 'WOW, what a stare. Great capture, one of my high score, good luck.', '2009-04-04 00:05:23.000000', NULL, 1),
(5417838, 778195, 30454, '<td valign="top">Excellent capture. Lighting is little too strong and it''s creating shadows on the other side. Still one of my top score, good luck.</td>', 'Excellent capture. Lighting is little too strong and it''s creating shadows on the other side. Still one of my top score, good luck.', '2009-04-04 00:06:47.000000', NULL, 1),
(5417887, 778576, 100687, '<td valign="top">I''m amazed you got this great of detail with your camera! $100 well spent. And always with the frames.. lol.</td>', 'I''m amazed you got this great of detail with your camera! $100 well spent. And always with the frames.. lol.', '2009-04-04 00:53:01.000000', NULL, 1),
