(5417901, 777145, 96751, '<td valign="top">Great subject, overprocessed IMO.</td>', 'Great subject, overprocessed IMO.', '2009-04-04 01:05:13.000000', NULL, 1),
(5417903, 778645, 96751, '<td valign="top">There is something very humorous about this capture.  But lighting is a bit flat.</td>', 'There is something very humorous about this capture.  But lighting is a bit flat.', '2009-04-04 01:06:03.000000', NULL, 1),
