(5419091, 778303, 97114, '<td valign="top">I really like the composition.</td>', 'I really like the composition.', '2009-04-04 23:23:07.000000', NULL, 1),
(5419103, 778293, 97114, '<td valign="top">I love this photo - it shows the true nature of these horses and the focus, colors are lovely.  The cloudy sky contrast adds to the shot.</td>', 'I love this photo - it shows the true nature of these horses and the focus, colors are lovely.  The cloudy sky contrast adds to the shot.', '2009-04-04 23:34:04.000000', NULL, 1),
